ROOT = Path(__file__).absolute().parent.parent
sys.path.insert(0, str(ROOT / "scripts"))
from scoped_fs import CapabilityHold, ScopedFSError, ScopedRoot
from private_workspace import (PrivateWorkspaceError, ensure_private_directory,
                               ensure_private_file, write_private_new)
from storage_ops import (StorageRefusal, StorageService, VERSION, canonical,
                         plan_sha256, render_storage, sha256, storage_capabilities)

FIXTURES = ROOT / "work" / "upgrade_v3" / "storage"
if os.name == "nt":
    import windows_scoped
    windows_scoped._WORK_ROOT = FIXTURES / ("private-adapter-" + uuid.uuid4().hex)


def fixture_directory():
    FIXTURES.mkdir(parents=True, exist_ok=True)
    path = FIXTURES / ("private-" + uuid.uuid4().hex)
    try:
        return ensure_private_directory(path, create=True, boundary=ROOT / "work")
    except PrivateWorkspaceError as exc:
        raise unittest.SkipTest("Actual filesystem cannot establish the required private namespace: " + exc.code) from exc


def private_child(parent, name):
    return ensure_private_directory(parent / name, create=True, boundary=ROOT / "work")


class StoragePrivacyAdmissionTests(unittest.TestCase):
    def test_unsafe_existing_output_root_refuses_before_selected_scope_access(self):
        FIXTURES.mkdir(parents=True, exist_ok=True)
        base = Path(tempfile.mkdtemp(prefix="unsafe-admission-", dir=FIXTURES))
        output = base / "output"
        output.mkdir(mode=0o755)
        try:
            ensure_private_directory(output)
        except PrivateWorkspaceError:
            pass
        else:
            self.skipTest("Ordinary creation was already private on this host; no permissions are broadened for the fixture")
        with mock.patch.object(StorageService, "_scope", side_effect=AssertionError("Selected scope must stay unopened")):
            with self.assertRaisesRegex(StorageRefusal, "Owner-private"):
                StorageService(output_root=output, quiet_workspace=True)
        self.assertEqual(list(output.iterdir()), [])
        with self.assertRaises(PrivateWorkspaceError):
            ensure_private_directory(output)

    def test_private_namespace_creation_or_actual_unsupported_hold(self):
        FIXTURES.mkdir(parents=True, exist_ok=True)
        output = FIXTURES / ("privacy-capability-" + uuid.uuid4().hex)
        try:
            ensure_private_directory(output, create=True, boundary=ROOT / "work")
        except PrivateWorkspaceError:
            # /mnt/c can report 0777 after a requested 0700 creation. A real
            # refusal is the required result; do not chmod, remount or move it.
            with self.assertRaisesRegex(StorageRefusal, "Owner-private"):
                StorageService(output_root=output, quiet_workspace=True)
            if output.exists():
                self.assertEqual(list(output.iterdir()), [])
        else:
            service = StorageService(output_root=output, quiet_workspace=True)
            self.assertEqual(service.output_root, output)
            ensure_private_directory(output)

    def test_output_privacy_is_rechecked_before_source_admission(self):
        base = fixture_directory()
        output = private_child(base, "output")
        service = StorageService(output_root=output, quiet_workspace=True)
        with mock.patch("storage_ops.ensure_private_directory", side_effect=PrivateWorkspaceError("private-owner-or-mode-refused")):
            with mock.patch("storage_ops.ScopedRoot", side_effect=AssertionError("No selected source should be opened")) as admission:
                with self.assertRaisesRegex(StorageRefusal, "Owner-private"):
                    service.assess_storage(roots=[base / "unopened-source"])
                admission.assert_not_called()
        self.assertEqual(list(output.iterdir()), [])


class PureStorageTests(unittest.TestCase):
    def test_quiet_workspace_and_output_scope_are_explicit(self):
        with self.assertRaises(StorageRefusal):
            StorageService(output_root=ROOT / "work" / "upgrade_v3" / "storage", quiet_workspace=False)
        with self.assertRaises(StorageRefusal):
            StorageService(output_root=ROOT / "scripts", quiet_workspace=True)
        with self.assertRaises(StorageRefusal):
            StorageService(output_root=ROOT / "work", quiet_workspace=True)

    def test_read_permission_and_mutation_cli_are_not_inferred(self):
        base = fixture_directory()
        output = base / "output"
        private_child(base, "output")
        service = StorageService(output_root=output, quiet_workspace=True)
        with self.assertRaisesRegex(StorageRefusal, "Explicit permission"):
            service.find_duplicates(inventory={}, content_read_authorized=False)
        self.assertFalse(storage_capabilities()["cli_mutation_enabled"])
        self.assertTrue(storage_capabilities()["requires_workflow_engine_gate"])

    def test_plan_hash_does_not_authenticate_owner(self):
        base = fixture_directory()
        output = base / "output"
        private_child(base, "output")
        service = StorageService(output_root=output, quiet_workspace=True)
        with self.assertRaisesRegex(StorageRefusal, "not proof of owner consent"):
            service.purge_quarantine(plan={"approved": True}, expected_plan_sha256="0" * 64)

    def _archive(self, *, name="payload/000001", content=b"fictional", external_attr=None):
        stream = io.BytesIO()
        with zipfile.ZipFile(stream, "w") as archive:
            info = zipfile.ZipInfo(name)
            info.create_system = 3
            info.external_attr = ((stat.S_IFREG | 0o600) << 16) if external_attr is None else external_attr
            archive.writestr(info, content)
        data = stream.getvalue()
        manifest = {"schema_version": VERSION, "kind": "backup_manifest", "archive_sha256": sha256(data),
                    "archive_bytes": len(data), "files": [{"entry": name, "root_id": "r001", "relative_path": "fictional.txt",
                                                              "size": len(content), "sha256": sha256(content)}],
                    "limits": {"max_entries": 100, "max_depth": 10, "max_file_bytes": 1000, "max_total_bytes": 1000}}
        return data, manifest

    def test_zip_verification_rejects_traversal_link_and_hash_mismatch(self):
        data, manifest = self._archive()
        self.assertTrue(StorageService._verify_zip(data, manifest))
        bad = copy.deepcopy(manifest)
        bad["files"][0]["relative_path"] = "../../escape.txt"
        with self.assertRaises(StorageRefusal):
            StorageService._verify_zip(data, bad)
        data2, manifest2 = self._archive(name="../escape.txt")
        with self.assertRaisesRegex(StorageRefusal, "Unsafe ZIP"):
            StorageService._verify_zip(data2, manifest2)
        data3, manifest3 = self._archive(external_attr=(stat.S_IFLNK | 0o777) << 16)
        with self.assertRaisesRegex(StorageRefusal, "nonordinary ZIP"):
            StorageService._verify_zip(data3, manifest3)
        bad = copy.deepcopy(manifest)
        bad["files"][0]["sha256"] = "0" * 64
        with self.assertRaisesRegex(StorageRefusal, "hash mismatch"):
            StorageService._verify_zip(data, bad)

    def test_zip_crc_corruption_and_extra_members_are_rejected(self):
        data, manifest = self._archive()
        damaged = bytearray(data)
        offset = data.index(b"fictional")
        damaged[offset] ^= 1
        damaged = bytes(damaged)
        manifest["archive_sha256"] = sha256(damaged)
        with self.assertRaisesRegex(StorageRefusal, "CRC"):
            StorageService._verify_zip(damaged, manifest)
        data, manifest = self._archive()
        stream = io.BytesIO(data)
        with zipfile.ZipFile(stream, "a") as archive:
            archive.writestr("unknown", b"fictional")
        changed = stream.getvalue()
        manifest["archive_sha256"] = sha256(changed)
        manifest["archive_bytes"] = len(changed)
        with self.assertRaisesRegex(StorageRefusal, "exact reviewed list"):
            StorageService._verify_zip(changed, manifest)

    def test_case_ambiguous_restore_and_protected_payload_are_rejected(self):
        data, manifest = self._archive()
        bad = copy.deepcopy(manifest)
        second = {**bad["files"][0], "entry": "payload/000002", "relative_path": "FICTIONAL.TXT"}
        bad["files"].append(second)
        with self.assertRaisesRegex(StorageRefusal, "Case-ambiguous"):
            StorageService._verify_zip(data, bad)
        bad = copy.deepcopy(manifest)
        bad["files"][0]["relative_path"] = ".ssh/id_ed25519"
        with self.assertRaisesRegex(StorageRefusal, "Protected"):
            StorageService._verify_zip(data, bad)
        bad["files"][0]["relative_path"] = ".local/share/keyrings/login.keyring"
        with self.assertRaisesRegex(StorageRefusal, "Protected"):
            StorageService._verify_zip(data, bad)


class NativeStorageTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        base = fixture_directory()
        try:
            with ScopedRoot(base, quiet_workspace=True, max_entries=100) as scope:
                scope.inspect("")
        except CapabilityHold as exc:
            raise unittest.SkipTest("Actual host lacks checked selected-root primitives: " + getattr(exc, "code", "capability_hold"))

    def setUp(self):
        self.base = fixture_directory()
        self.source = self.base / "source"
        self.output = self.base / "output"
        private_child(self.base, "source")
        private_child(self.base, "output")
        write_private_new(self.source / "readme.txt", b"fictional document\n")
        write_private_new(self.source / "copy.txt", b"fictional document\n")
        write_private_new(self.source / "large.bin", b"different fictional bytes" * 100)
        folder = self.source / "notes"
        private_child(self.source, "notes")
        write_private_new(folder / "draft.md", b"fictional draft\n")
        self.service = StorageService(output_root=self.output, quiet_workspace=True)

    def inventory(self):
        return self.service.assess_storage(roots=[self.source])

    def backup(self, inventory=None, selected=None):
        inventory = inventory or self.inventory()
        selected = selected or [row["key"] for row in inventory["entries"] if row["kind"] == "file"]
        plan = self.service.plan_backup(inventory=inventory, selected=selected,
                                        destination=self.output / "fictional.zip", content_read_authorized=True)
        return plan, self.service.create_backup(plan=plan, expected_plan_sha256=plan_sha256(plan))

    def probe(self, backup):
        plan = self.service.plan_restore(receipt=backup, destination=self.output / "recovery-probe")
        return self.service.restore_backup(plan=plan, expected_plan_sha256=plan_sha256(plan))

    def test_private_archive_probe_and_records_actual_permissions(self):
        plan, backup = self.backup(selected=["r001/readme.txt"])
        restored = self.probe(backup)
        for path in (Path(backup["archive"]), Path(backup["manifest"]),
                     self.output / backup["attempt"], self.output / restored["attempt"],
                     self.output / ("outcome-backup-" + plan_sha256(plan) + ".json"),
                     self.output / ("outcome-restore-" + restored["plan_sha256"] + ".json"),
                     Path(restored["destination"]) / "r001" / "readme.txt"):
            ensure_private_file(path)
        ensure_private_directory(Path(restored["destination"]))
        ensure_private_directory(Path(restored["destination"]) / "r001")

    @unittest.skipUnless(os.name == "nt", "Windows rename preserves file DACL; POSIX uses private directory traversal")
    def test_windows_broad_quarantine_source_holds_without_acl_change(self):
        source = Path(tempfile.mkdtemp(prefix="ordinary-public-source-", dir=FIXTURES))
        target = source / "public-fixture.txt"
        target.write_bytes(b"fictional public source")
        try:
            ensure_private_file(target)
        except PrivateWorkspaceError:
            pass
        else:
            self.skipTest("Ordinary source inherited a private file DACL; no ACLs are broadened to force this fixture")
        inventory = self.service.assess_storage(roots=[source])
        with mock.patch.object(self.service, "_hashed", side_effect=AssertionError("No source bytes before the privacy hold")) as hashing:
            with self.assertRaisesRegex(StorageRefusal, "Owner-private"):
                self.service.plan_cleanup(inventory=inventory, selected=["r001/public-fixture.txt"],
                                          quarantine_destination=self.output / "quarantine", content_read_authorized=True,
                                          recovery_required=False)
            hashing.assert_not_called()
        with self.assertRaises(PrivateWorkspaceError):
            ensure_private_file(target)
        self.assertTrue(target.exists())
        self.assertEqual(list(self.output.iterdir()), [])

    @unittest.skipUnless(os.name == "nt", "Actual Windows DACL preservation regression")
    def test_private_windows_quarantine_and_restore_recheck_file_acl(self):
        inventory = self.inventory()
        plan = self.service.plan_cleanup(inventory=inventory, selected=["r001/readme.txt"],
                                          quarantine_destination=self.output / "quarantine", content_read_authorized=True,
                                          recovery_required=False)
        receipt = self.service.quarantine(plan=plan, expected_plan_sha256=plan_sha256(plan))
        ensure_private_directory(self.output / "quarantine")
        ensure_private_file(self.output / receipt["records"][0]["quarantine_record"]["relative_path"])
        restore = self.service.plan_quarantine_restore(receipt=receipt)
        self.service.restore_quarantine(plan=restore, expected_plan_sha256=plan_sha256(restore))
        ensure_private_file(self.source / "readme.txt")
        self.assertTrue((self.source / "readme.txt").exists())

    def test_metadata_prunes_protected_tree_and_reports_deterministically(self):
        protected = self.source / "chatgpt"
        protected.mkdir()
        (protected / "must-not-be-opened.txt").write_bytes(b"fictional protected marker")
        (self.source / ".env").write_bytes(b"fictional never-open marker")
        keyrings = self.source / "keyrings"
        keyrings.mkdir()
        (keyrings / "login.keyring").write_bytes(b"fictional never-open keychain marker")
        inventory = self.inventory()
        self.assertFalse(inventory["content_read"])
        self.assertEqual(inventory["summary"]["files"], 4)
        self.assertEqual(inventory["summary"]["excluded"], 3)
        self.assertNotIn("must-not-be-opened", json.dumps(inventory))
        self.assertEqual(inventory["inventory_sha256"], self.inventory()["inventory_sha256"])
        report = render_storage(inventory)
        self.assertIn("ordinary files", report)
        self.assertIn("Physical allocation", report)
        self.assertIn(".txt | 2", report)
        self.assertEqual(report, render_storage(inventory))

    def test_duplicates_are_hash_bound_but_do_not_authorize_removal(self):
        inventory = self.inventory()
        result = self.service.find_duplicates(inventory=inventory, content_read_authorized=True)
        self.assertEqual(len(result["groups"]), 1)
        self.assertEqual(len(result["groups"][0]["files"]), 2)
        self.assertEqual(result["logical_byte_opportunity"], len(b"fictional document\n"))
        self.assertIsNone(result["reclaimable_bytes"])
        self.assertFalse(result["removal_authorized"])

    def test_metadata_logical_size_does_not_consume_content_read_budget(self):
        large = self.source / "fictional-sparse.bin"
        with large.open("xb") as stream:
            stream.truncate(2 * 1024 * 1024)
        inventory = self.service.assess_storage(roots=[self.source], limits={"max_total_bytes": 1024})
        self.assertGreater(inventory["summary"]["logical_bytes"], 2 * 1024 * 1024)
        self.assertFalse(inventory["content_read"])
        with self.assertRaisesRegex(StorageRefusal, "total read budget"):
            self.service.plan_backup(inventory=inventory, selected=["r001/fictional-sparse.bin"],
                                      destination=self.output / "fictional.zip", content_read_authorized=True)
        self.assertEqual(list(self.output.iterdir()), [])

    def test_browser_channels_and_explicit_profile_roots_are_pruned(self):
        for relative in (".config/microsoft-edge", ".config/google-chrome-beta", "Library/Application Support/Microsoft Edge"):
            folder = self.source / relative
            folder.mkdir(parents=True)
            (folder / "Local State").write_bytes(b"fictional must-not-read marker")
        custom = self.source / "custom-profile-42"
        custom.mkdir()
        (custom / "Preferences").write_bytes(b"fictional must-not-read marker")
        service = StorageService(output_root=self.output, quiet_workspace=True, protected_roots=[custom])
        inventory = service.assess_storage(roots=[self.source])
        self.assertEqual(inventory["summary"]["excluded"], 4)
        self.assertNotIn("must-not-read marker", json.dumps(inventory))
        self.assertFalse(any(row["relative_path"].endswith(("Local State", "Preferences")) for row in inventory["entries"]))

    def test_unknown_file_stale_hash_and_caps_hold(self):
        inventory = self.inventory()
        selected = ["r001/readme.txt"]
        plan = self.service.plan_backup(inventory=inventory, selected=selected, destination=self.output / "fictional.zip", content_read_authorized=True)
        (self.source / "unknown.txt").write_bytes(b"fictional newly-created entry")
        with self.assertRaisesRegex(StorageRefusal, "inventory changed"):
            self.service.create_backup(plan=plan, expected_plan_sha256=plan_sha256(plan))
        self.assertFalse((self.output / "fictional.zip").exists())
        with self.assertRaises(StorageRefusal):
            self.service.assess_storage(roots=[self.source], limits={"max_entries": 1})
        current = self.inventory()
        stale = copy.deepcopy(current)
        stale["entries"][0]["size"] += 1
        with self.assertRaisesRegex(StorageRefusal, "binding"):
            self.service.find_duplicates(inventory=stale, content_read_authorized=True)
        misleading = copy.deepcopy(current)
        misleading["summary"]["logical_bytes"] = 0
        with self.assertRaisesRegex(StorageRefusal, "derived report facts"):
            self.service.find_duplicates(inventory=misleading, content_read_authorized=True)

    def test_read_only_preflight_does_not_consume_a_plan(self):
        inventory = self.inventory()
        plan = self.service.plan_backup(inventory=inventory, selected=["r001/readme.txt"],
                                        destination=self.output / "fictional.zip", content_read_authorized=True)
        evidence = self.service.check_preconditions(plan=plan, expected_plan_sha256=plan_sha256(plan))
        self.assertFalse(evidence["mutation_performed"])
        self.assertEqual(list(self.output.iterdir()), [])
        invented = {"schema_version": VERSION, "kind": "backup_receipt", "plan_sha256": plan_sha256(plan)}
        with self.assertRaises((StorageRefusal, ScopedFSError)):
            self.service.verify_outcome(plan=plan, expected_plan_sha256=plan_sha256(plan), receipt=invented)
        (self.source / "new.txt").write_bytes(b"fictional changed scope")
        with self.assertRaisesRegex(StorageRefusal, "inventory changed"):
            self.service.check_preconditions(plan=plan, expected_plan_sha256=plan_sha256(plan))

    def test_direct_mutation_payload_cannot_admit_protected_content(self):
        protected = self.source / ".env"
        protected.write_bytes(b"fictional protected marker")
        inventory = self.inventory()
        backup = self.service.plan_backup(inventory=inventory, selected=["r001/readme.txt"],
                                          destination=self.output / "fictional.zip", content_read_authorized=True)
        excluded = next(row for row in inventory["entries"] if row["key"] == "r001/.env")
        forged = {key: value for key, value in excluded.items() if key != "reason"}
        forged.update(kind="file", sha256=sha256(b"fictional protected marker"), entry="payload/000001")
        backup["files"] = [forged]
        with self.assertRaisesRegex(StorageRefusal, "excluded"):
            self.service.create_backup(plan=backup, expected_plan_sha256=plan_sha256(backup))
        cleanup = self.service.plan_cleanup(inventory=inventory, selected=["r001/readme.txt"],
                                            quarantine_destination=self.output / "quarantine", content_read_authorized=True,
                                            recovery_required=False)
        cleanup["files"] = [{key: value for key, value in forged.items() if key != "entry"}]
        with self.assertRaisesRegex(StorageRefusal, "excluded"):
            self.service.quarantine(plan=cleanup, expected_plan_sha256=plan_sha256(cleanup))
        self.assertTrue(protected.exists())
        self.assertEqual(list(self.output.iterdir()), [])

    def test_imported_quarantine_receipt_cannot_purge_output_artifacts(self):
        folder = self.output / "invented-quarantine"
        folder.mkdir()
        (folder / "000001").write_bytes(b"fictional retained recovery")
        receipt = {"schema_version": VERSION, "kind": "quarantine_receipt", "plan_sha256": "0" * 64,
                   "quarantine_destination": str(folder), "records": [], "recovery_required": False,
                   "recovery_backup": None, "recovery_verification": None, "attempt": "invented"}
        with self.assertRaises((StorageRefusal, ScopedFSError)):
            self.service.plan_purge(receipt=receipt)
        self.assertTrue((folder / "000001").exists())

    def test_overlapping_roots_and_inside_source_output_hold(self):
        with self.assertRaisesRegex(StorageRefusal, "Overlapping"):
            self.service.assess_storage(roots=[self.source, self.source / "notes"])
        inventory = self.service.assess_storage(roots=[self.base])
        with self.assertRaisesRegex(StorageRefusal, "outside every"):
            self.service.plan_backup(inventory=inventory, selected=["r001/source/readme.txt"],
                                     destination=self.output / "inside.zip", content_read_authorized=True)

    def test_generated_recovery_and_evidence_are_not_host_cleanup_targets(self):
        retained = self.output / "retained"
        retained.mkdir()
        (retained / "fictional-backup.zip").write_bytes(b"fictional protected archive marker")
        inventory = self.service.assess_storage(roots=[retained])
        with self.assertRaisesRegex(StorageRefusal, "stay protected"):
            self.service.plan_cleanup(inventory=inventory, selected=["r001/fictional-backup.zip"],
                                      quarantine_destination=self.output / "quarantine", content_read_authorized=True,
                                      recovery_required=False)

    def test_verified_backup_restore_and_immutable_archive(self):
        plan, receipt = self.backup()
        attempt = json.loads((self.output / receipt["attempt"]).read_bytes())
        self.assertEqual(attempt["exact_plan"], plan)
        self.assertEqual(attempt["plan_sha256"], plan_sha256(plan))
        verified = self.service.verify_backup(receipt=receipt)
        self.assertTrue(verified["verified"])
        self.assertTrue(self.service.verify_outcome(plan=plan, expected_plan_sha256=plan_sha256(plan), receipt=receipt)["verification_passed"])
        self.assertFalse(receipt["encryption"])
        self.assertEqual(len(verified["manifest"]["files"]), 4)
        restore = self.service.plan_restore(receipt=receipt, destination=self.output / "restored")
        outcome = self.service.restore_backup(plan=restore, expected_plan_sha256=plan_sha256(restore))
        self.assertTrue(outcome["verified"])
        self.assertTrue(self.service.verify_outcome(plan=restore, expected_plan_sha256=plan_sha256(restore), receipt=outcome)["verification_passed"])
        self.assertEqual((self.output / "restored" / "r001" / "readme.txt").read_bytes(), b"fictional document\n")
        self.assertEqual((self.output / "restored" / "r001" / "notes" / "draft.md").read_bytes(), b"fictional draft\n")
        with self.assertRaises((StorageRefusal, ScopedFSError, FileExistsError)):
            self.service.create_backup(plan=plan, expected_plan_sha256=plan_sha256(plan))
        with self.assertRaises((StorageRefusal, ScopedFSError, FileExistsError)):
            self.service.plan_restore(receipt=receipt, destination=self.output / "restored")

    def test_stored_corruption_is_not_verified(self):
        plan, receipt = self.backup()
        path = Path(receipt["archive"])
        content = bytearray(path.read_bytes())
        content[0] ^= 1
        path.write_bytes(content)
        with self.assertRaises((StorageRefusal, ScopedFSError)):
            self.service.verify_backup(receipt=receipt)

    def test_skipped_unbacked_files_visible_and_required_recovery_holds(self):
        inventory = self.inventory()
        selected = ["r001/readme.txt"]
        plan, receipt = self.backup(inventory, selected)
        self.assertTrue(any(row["key"] == "r001/copy.txt" and "not backed up" in row["reason"] for row in plan["skipped"]))
        with self.assertRaisesRegex(StorageRefusal, "Required recovery"):
            self.service.plan_cleanup(inventory=inventory, selected=selected, quarantine_destination=self.output / "quarantine", content_read_authorized=True)
        with self.assertRaisesRegex(StorageRefusal, "restoration probe"):
            self.service.plan_cleanup(inventory=inventory, selected=selected, quarantine_destination=self.output / "quarantine", content_read_authorized=True, recovery_backup=receipt)
        probe = self.probe(receipt)
        with self.assertRaisesRegex(StorageRefusal, "does not cover"):
            self.service.plan_cleanup(inventory=inventory, selected=["r001/copy.txt"], quarantine_destination=self.output / "quarantine", content_read_authorized=True, recovery_backup=receipt, recovery_verification=probe)
        with self.assertRaisesRegex(StorageRefusal, "protected"):
            self.service.plan_cleanup(inventory=inventory, selected=selected, quarantine_destination=self.output / "quarantine", content_read_authorized=True, recovery_backup=receipt, protected=selected)

    def test_quarantine_restore_and_distinct_purge_plan(self):
        inventory = self.inventory()
        _, backup = self.backup(inventory)
        probe = self.probe(backup)
        cleanup = self.service.plan_cleanup(inventory=inventory, selected=["r001/readme.txt"],
                                            quarantine_destination=self.output / "quarantine", content_read_authorized=True, recovery_backup=backup, recovery_verification=probe)
        self.assertEqual(cleanup["cost"]["expected_free_space_gain_bytes"], 0)
        try:
            receipt = self.service.quarantine(plan=cleanup, expected_plan_sha256=plan_sha256(cleanup))
        except CapabilityHold as exc:
            self.skipTest("Actual filesystem lacks safe no-overwrite move: " + getattr(exc, "code", "capability_hold"))
        self.assertFalse((self.source / "readme.txt").exists())
        self.assertTrue(self.service.verify_outcome(plan=cleanup, expected_plan_sha256=plan_sha256(cleanup), receipt=receipt)["verification_passed"])
        purge = self.service.plan_purge(receipt=receipt)
        self.assertTrue(purge["irreversible"])
        self.assertTrue(purge["requires_separate_owner_approval"])
        with self.assertRaises(StorageRefusal):
            self.service.purge_quarantine(plan=cleanup, expected_plan_sha256=plan_sha256(cleanup))
        restore = self.service.plan_quarantine_restore(receipt=receipt)
        restored = self.service.restore_quarantine(plan=restore, expected_plan_sha256=plan_sha256(restore))
        self.assertTrue(self.service.verify_outcome(plan=restore, expected_plan_sha256=plan_sha256(restore), receipt=restored)["verification_passed"])
        self.assertEqual((self.source / "readme.txt").read_bytes(), b"fictional document\n")

    def test_required_restoration_probe_is_rechecked(self):
        inventory = self.inventory()
        _, backup = self.backup(inventory, ["r001/readme.txt"])
        probe = self.probe(backup)
        (self.output / "recovery-probe" / "r001" / "readme.txt").write_bytes(b"fictional changed restoration")
        with self.assertRaises((StorageRefusal, ScopedFSError)):
            self.service.plan_cleanup(inventory=inventory, selected=["r001/readme.txt"],
                                      quarantine_destination=self.output / "quarantine", content_read_authorized=True,
                                      recovery_backup=backup, recovery_verification=probe)

    def test_unknown_quarantine_file_blocks_purge(self):
        inventory = self.inventory()
        cleanup = self.service.plan_cleanup(inventory=inventory, selected=["r001/readme.txt"],
                                            quarantine_destination=self.output / "quarantine", content_read_authorized=True, recovery_required=False)
        try:
            receipt = self.service.quarantine(plan=cleanup, expected_plan_sha256=plan_sha256(cleanup))
        except CapabilityHold as exc:
            self.skipTest("Actual filesystem lacks safe no-overwrite move: " + getattr(exc, "code", "capability_hold"))
        (self.output / "quarantine" / "unknown.txt").write_bytes(b"fictional unregistered")
        with self.assertRaisesRegex(StorageRefusal, "Unknown"):
            self.service.plan_purge(receipt=receipt)

    def test_purge_removes_only_reviewed_quarantine_bytes(self):
        inventory = self.inventory()
        cleanup = self.service.plan_cleanup(inventory=inventory, selected=["r001/readme.txt"],
                                            quarantine_destination=self.output / "quarantine", content_read_authorized=True, recovery_required=False)
        try:
            receipt = self.service.quarantine(plan=cleanup, expected_plan_sha256=plan_sha256(cleanup))
        except CapabilityHold as exc:
            self.skipTest("Actual filesystem lacks safe no-overwrite move: " + getattr(exc, "code", "capability_hold"))
        purge = self.service.plan_purge(receipt=receipt)
        result = self.service.purge_quarantine(plan=purge, expected_plan_sha256=plan_sha256(purge))
        self.assertTrue(result["irreversible"])
        self.assertTrue(self.service.verify_outcome(plan=purge, expected_plan_sha256=plan_sha256(purge), receipt=result)["verification_passed"])
        self.assertEqual(len(result["removed"]), 1)
        self.assertTrue((self.source / "copy.txt").exists())
        self.assertTrue((self.source / "large.bin").exists())

    def test_symlink_and_hardlink_never_form_duplicates(self):
        linked = self.source / "linked.txt"
        try:
            os.symlink(self.source / "readme.txt", linked)
        except (OSError, NotImplementedError):
            self.skipTest("This native fixture filesystem does not support symlink creation")
        with self.assertRaises((StorageRefusal, ScopedFSError)):
            self.inventory()
        # Remove only the exact synthetic link we just created, never recursion.
        linked.unlink()
        try:
            os.link(self.source / "readme.txt", linked)
        except (OSError, NotImplementedError):
            self.skipTest("This native fixture filesystem does not support hardlinks")
        with self.assertRaises((StorageRefusal, ScopedFSError)):
            self.inventory()


